  // Block all downstream pending steps (S2-F2)
  let foundActive = false;
  for (const step of run.steps) {
    if (step === active) { foundActive = true; continue; }
    if (foundActive && step.status === "pending") {
      step.status = "blocked";
      step.note = `Blocked: upstream ${active.role} ${status}`;
    }
  }

  // Mission status follows the worst step
  run.status = status;
  run.completedAt = new Date().toISOString();

  return active;
}

export function failStep(run, status, reason, cwd) {
  const explicitCwd = arguments.length >= 4;
  if (status !== "partial" && status !== "failed") {
    throw new Error(`Invalid fail status: "${status}". Use "partial" or "failed"`);
  }

  const active = run.steps.find((s) => s.status === "active");
  if (!active) {
    throw new Error("No active step to fail");
  }

  active.status = status;
  active.note = reason;
  active.completedAt = new Date().toISOString();

  // Block all downstream pending steps (S2-F2)
  let foundActive = false;
  for (const step of run.steps) {
    if (step === active) { foundActive = true; continue; }
    if (foundActive && step.status === "pending") {
      step.status = "blocked";
      step.note = `Blocked: upstream ${active.role} ${status}`;
    }
  }

  // Mission status follows the worst step
  run.status = status;
  run.completedAt = new Date().toISOString();

  if (explicitCwd) recordMissionOutcome(run, cwd);
  return active;
}

function recordMissionOutcome(run, cwd) {
  if (!cwd) return false;
  const mission = run && run.missionKey ? getMission(run.missionKey) : null;
  const view = mission && mission.pack ? { ...run, packKey: mission.pack } : run;
  return recordRunOutcome(view, cwd);

export function juryCheck(critics, items, { seed = DEFAULT_SEED, B = DEFAULT_BOOTSTRAP } = {}) {
  const reports = criticReports(critics, items, seed, B);
  const pairs = diversityMatrix(critics, items);
  const inverted = [];
  for (let i = 0; i < reports.length; i++) {
    const row = reports[i];
    if (row.ci && row.ci.high < 0.5) inverted.push(row.id);
  }
  const duplicates = [];
  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (pair.errorConsistency !== null && pair.errorConsistency >= DUPLICATE_KAPPA) {
      duplicates.push({ a: pair.a, b: pair.b, errorConsistency: pair.errorConsistency });
    }
  }
  return {
    items: items.length,
    groups: sortedGroups(items).length,
    seed,
    bootstrap: B,
    critics: reports,
    pairs,
    inverted,
    duplicates,
  };
}

